-- Colors generated by pywal
--
-- Was: source = ~/.cache/wal/colors-hyprland.conf
--
-- Lua cannot `source` a hyprlang file, so this reads the same file that pywal
-- already generates ($colorN = rgb(xxxxxx) lines) and exposes the values as a
-- table, e.g. colors.color7.
local colors = {}

local file = io.open(os.getenv("HOME") .. "/.cache/wal/colors-hyprland.conf", "r")
if file then
    for line in file:lines() do
        local name, value = line:match("^%$(%w+)%s*=%s*(.-)%s*$")
        if name then
            colors[name] = value
        end
    end
    file:close()
end

return colors
